int isalpha(int c){ return isupper(c)||islower(c); }
int isalnum(int c){ return isalpha(c)||isdigit(c); }
int iscntrl(int c){ return (c>=0&&c<32)||c==127; }
int isprint(int c){ return c>=32&&c<127; }
int isgraph(int c){ return c>32&&c<127; }
int ispunct(int c){ return isprint(c)&&c!=' '&&!isalnum(c); }
int tolower(int c){ return isupper(c)?c+32:c; }
int toupper(int c){ return islower(c)?c-32:c; }

/* ---- number parsing ---- */
long strtol(const char *s, char **end, int base){
    const char *p=s; while(isspace((unsigned char)*p)) p++;
    int neg=0; if(*p=='+'||*p=='-'){ neg=*p=='-'; p++; }
    if((base==0||base==16) && p[0]=='0' && (p[1]=='x'||p[1]=='X')){ p+=2; base=16; }
    else if(base==0 && p[0]=='0'){ base=8; }
    else if(base==0){ base=10; }
    long v=0;
    for(;;p++){ int d; char c=*p; if(c>='0'&&c<='9') d=c-'0'; else if(c>='a'&&c<='z') d=c-'a'+10; else if(c>='A'&&c<='Z') d=c-'A'+10; else break; if(d>=base) break; v=v*base+d; }
    if(end) *end=(char*)p; return neg?-v:v;
}
unsigned long strtoul(const char *s, char **end, int base){ return (unsigned long)strtol(s,end,base); }
int atoi(const char *s){ return (int)strtol(s,0,10); }
long atol(const char *s){ return strtol(s,0,10); }
double strtod(const char *s, char **end){
    const char *p=s; while(isspace((unsigned char)*p)) p++;
    int neg=0; if(*p=='+'||*p=='-'){ neg=*p=='-'; p++; }
    double v=0; while(isdigit((unsigned char)*p)){ v=v*10+(*p-'0'); p++; }
    if(*p=='.'){ p++; double f=0.1; while(isdigit((unsigned char)*p)){ v+=(*p-'0')*f; f*=0.1; p++; } }
    if(end) *end=(char*)p; return neg?-v:v;
}
double atof(const char *s){ return strtod(s,0); }

int abs(int x){ return x<0?-x:x; }
long labs(long x){ return x<0?-x:x; }
double fabs(double x){ return x<0?-x:x; }

static unsigned long __rnd = 1;
int rand(void){ __rnd = __rnd*1103515245u + 12345u; return (int)((__rnd>>16)&0x7fff); }
void srand(unsigned int s){ __rnd = s; }

void qsort(void *base, unsigned long n, unsigned long sz, int (*cmp)(const void*,const void*)){
    /* simple insertion sort; lc-debt: O(n^2); fine for small n */
    char *a=base; char tmp[256];
    for(unsigned long i=1;i<n;i++){
        for(unsigned long j=i;j>0;j--){
            char *x=a+(j-1)*sz, *y=a+j*sz;
            if(cmp(x,y)<=0) break;
            memcpy(tmp,x,sz); memcpy(x,y,sz); memcpy(y,tmp,sz);
        }
    }
}
void *bsearch(const void *key, const void *base, unsigned long n, unsigned long sz, int (*cmp)(const void*,const void*)){
    unsigned long lo=0, hi=n;
    while(lo<hi){ unsigned long mid=(lo+hi)/2; const char *e=(const char*)base+mid*sz; int r=cmp(key,e); if(r==0) return (void*)e; if(r<0) hi=mid; else lo=mid+1; }
    return 0;
}

