/* ---- exit/abort/atexit/assert ---- */
static void (*atexit_fns[32])(void);
static int atexit_n = 0;
int atexit(void (*fn)(void)){ if(atexit_n<32) atexit_fns[atexit_n++]=fn; return 0; }
void exit(int code){ (void)code; for(int i=atexit_n-1;i>=0;i--) atexit_fns[i](); for(;;){} }
void abort(void){ for(;;){} }

/* stdio + printf/scanf for the freestanding libc. */
#include <stddef.h>
#include <stdint.h>
#include <stdarg.h>

extern long read(int, void*, unsigned long);
extern long write(int, const void*, unsigned long);
extern int open(const char*, int, ...);
extern int close(int);
extern long lseek(int, long, int);
extern void *malloc(unsigned long);
extern void free(void*);
extern unsigned long strlen(const char*);
extern int isspace(int);
extern int isdigit(int);

#define O_RDONLY 0
#define O_WRONLY 1
#define O_RDWR   2
#define O_CREAT  64
#define O_TRUNC  512
#define O_APPEND 1024

struct _IO_FILE { int fd; int eof; int err; int unget; };
typedef struct _IO_FILE FILE;

static FILE _f_stdin  = { 0, 0, 0, -1 };
static FILE _f_stdout = { 1, 0, 0, -1 };
static FILE _f_stderr = { 2, 0, 0, -1 };
FILE *stdin  = &_f_stdin;
FILE *stdout = &_f_stdout;
FILE *stderr = &_f_stderr;

FILE *fopen(const char *path, const char *mode){
    int flags = 0;
    if(mode[0]=='r') flags = (mode[1]=='+'||mode[2]=='+') ? O_RDWR : O_RDONLY;
    else if(mode[0]=='w') flags = ((mode[1]=='+'||mode[2]=='+') ? O_RDWR : O_WRONLY) | O_CREAT | O_TRUNC;
    else if(mode[0]=='a') flags = ((mode[1]=='+'||mode[2]=='+') ? O_RDWR : O_WRONLY) | O_CREAT | O_APPEND;
    else return 0;
    int fd = open(path, flags, 0666);
    if(fd < 0) return 0;
    FILE *f = malloc(sizeof(FILE));
    f->fd = fd; f->eof = 0; f->err = 0; f->unget = -1;
    return f;
}
FILE *fdopen(int fd, const char *mode){ (void)mode; FILE *f=malloc(sizeof(FILE)); f->fd=fd; f->eof=0; f->err=0; f->unget=-1; return f; }
int fclose(FILE *f){ if(!f) return -1; int r = close(f->fd); if(f!=&_f_stdin&&f!=&_f_stdout&&f!=&_f_stderr) free(f); return r; }

unsigned long fread(void *p, unsigned long sz, unsigned long n, FILE *f){
    if(sz==0||n==0) return 0;
    unsigned long total = sz*n, got = 0;
    char *b = p;
    if(f->unget>=0 && total>0){ *b++ = (char)f->unget; f->unget=-1; got=1; }
    while(got < total){
        long r = read(f->fd, b+ (got?0:0) , total-got);
        /* note: b already advanced by unget above */
        if(r <= 0){ if(r==0) f->eof=1; else f->err=1; break; }
        got += r; b += r;
    }
    return got / sz;
}
unsigned long fwrite(const void *p, unsigned long sz, unsigned long n, FILE *f){
    if(sz==0||n==0) return 0;
    unsigned long total = sz*n, put = 0;
    const char *b = p;
    while(put < total){
        long r = write(f->fd, b+put, total-put);
        if(r <= 0){ f->err=1; break; }
        put += r;
    }
    return put / sz;
}
int fseek(FILE *f, long off, int whence){ long r = lseek(f->fd, off, whence); f->unget=-1; f->eof=0; return r<0 ? -1 : 0; }
long ftell(FILE *f){ return lseek(f->fd, 0, 1); }
void rewind(FILE *f){ lseek(f->fd,0,0); f->eof=0; f->err=0; f->unget=-1; }
int fflush(FILE *f){ (void)f; return 0; }
int feof(FILE *f){ return f->eof; }
int ferror(FILE *f){ return f->err; }
void clearerr(FILE *f){ f->eof=0; f->err=0; }
int fileno(FILE *f){ return f->fd; }
int remove(const char *p){ (void)p; return -1; }

int fgetc(FILE *f){ if(f->unget>=0){ int c=f->unget; f->unget=-1; return c; } unsigned char c; long r=read(f->fd,&c,1); if(r==1) return c; f->eof=1; return -1; }
int getc(FILE *f){ return fgetc(f); }
int getchar(void){ return fgetc(&_f_stdin); }
int ungetc(int c, FILE *f){ if(c==-1) return -1; f->unget=(unsigned char)c; f->eof=0; return c; }
int fputc(int c, FILE *f){ unsigned char b=(unsigned char)c; if(write(f->fd,&b,1)!=1){ f->err=1; return -1; } return c; }
int putc(int c, FILE *f){ return fputc(c,f); }
int putchar(int c){ return fputc(c,&_f_stdout); }
int fputs(const char *s, FILE *f){ unsigned long n=strlen(s); return fwrite(s,1,n,f)==n ? 0 : -1; }
int puts(const char *s){ unsigned long n=strlen(s); if(fwrite(s,1,n,&_f_stdout)!=n) return -1; fputc('\n',&_f_stdout); return 0; }
char *fgets(char *s, int n, FILE *f){ int i=0; while(i<n-1){ int c=fgetc(f); if(c==-1){ if(i==0) return 0; break; } s[i++]=(char)c; if(c=='\n') break; } s[i]=0; return s; }
void setbuf(FILE *f, char *b){ (void)f;(void)b; }
int setvbuf(FILE *f, char *b, int m, unsigned long sz){ (void)f;(void)b;(void)m;(void)sz; return 0; }

/* ---- formatted output core ---- */
struct outbuf { char *buf; unsigned long cap; unsigned long len; };
static void ob_put(struct outbuf *o, char c){ if(o->len < o->cap) o->buf[o->len]=c; o->len++; }
static void ob_str(struct outbuf *o, const char *s, int n){ for(int i=0;i<n;i++) ob_put(o,s[i]); }

static int u2s(unsigned long long v, int base, int upper, char *out){
    const char *dig = upper ? "0123456789ABCDEF" : "0123456789abcdef";
    char tmp[24]; int i=0;
    if(v==0) tmp[i++]='0';
    while(v){ tmp[i++]=dig[v%base]; v/=base; }
    int n=i; for(int j=0;j<n;j++) out[j]=tmp[n-1-j];
    return n;
}

int _vformat(char *buf, unsigned long cap, const char *fmt, va_list ap){
    struct outbuf o = { buf, cap?cap-1:0, 0 };
    for(; *fmt; fmt++){
        if(*fmt != '%'){ ob_put(&o,*fmt); continue; }
        fmt++;
        int left=0, zero=0, plus=0, space=0, alt=0;
        for(;;fmt++){
            if(*fmt=='-') left=1; else if(*fmt=='0') zero=1; else if(*fmt=='+') plus=1;
            else if(*fmt==' ') space=1; else if(*fmt=='#') alt=1; else break;
        }
        int width=0; int havewidth=0;
        if(*fmt=='*'){ width=va_arg(ap,int); havewidth=1; fmt++; if(width<0){ left=1; width=-width; } }
        else while(isdigit((unsigned char)*fmt)){ width=width*10+(*fmt-'0'); havewidth=1; fmt++; }
        int prec=-1;
        if(*fmt=='.'){ fmt++; prec=0; if(*fmt=='*'){ prec=va_arg(ap,int); fmt++; if(prec<0) prec=-1; } else while(isdigit((unsigned char)*fmt)){ prec=prec*10+(*fmt-'0'); fmt++; } }
        int lng=0; /* 0=int,1=long,2=long long,-1=short */
        for(;;){ if(*fmt=='l'){ lng++; fmt++; } else if(*fmt=='h'){ lng--; fmt++; } else if(*fmt=='z'||*fmt=='j'||*fmt=='t'){ lng=1; fmt++; } else if(*fmt=='L'){ lng=2; fmt++; } else break; }
        char c=*fmt;
        char numbuf[32]; int nlen; const char *prefix=""; int preflen=0; char sign=0;
        if(c=='d'||c=='i'){
            long long v;
            if(lng>=2) v=va_arg(ap,long long); else v=va_arg(ap,long);
            unsigned long long uv;
            if(v<0){ sign='-'; uv=(unsigned long long)(-v); } else { uv=(unsigned long long)v; if(plus) sign='+'; else if(space) sign=' '; }
            nlen=u2s(uv,10,0,numbuf);
        } else if(c=='u'||c=='x'||c=='X'||c=='o'){
            unsigned long long uv;
            if(lng>=2) uv=va_arg(ap,unsigned long long); else uv=va_arg(ap,unsigned long);
            int base = c=='o'?8:(c=='u'?10:16);
            nlen=u2s(uv,base,c=='X',numbuf);
            if(alt && uv){ if(c=='x'){ prefix="0x"; preflen=2; } else if(c=='X'){ prefix="0X"; preflen=2; } else if(c=='o'){ prefix="0"; preflen=1; } }
        } else if(c=='p'){
            unsigned long uv=va_arg(ap,unsigned long);
            nlen=u2s(uv,16,0,numbuf); prefix="0x"; preflen=2;
            /* treat like %#x */
        } else if(c=='c'){
            char ch=(char)va_arg(ap,int);
            int pad=width-1; if(!left) while(pad-->0) ob_put(&o,' ');
            ob_put(&o,ch); if(left) while(pad-->0) ob_put(&o,' ');
            continue;
        } else if(c=='s'){
            const char *s=va_arg(ap,const char*); if(!s) s="(null)";
            int sl=0; while(s[sl] && (prec<0 || sl<prec)) sl++;
            int pad=width-sl; if(!left) while(pad-->0) ob_put(&o,' ');
            ob_str(&o,s,sl); if(left) while(pad-->0) ob_put(&o,' ');
            continue;
        } else if(c=='f'||c=='F'||c=='g'||c=='G'||c=='e'||c=='E'){
            (void)va_arg(ap,long long); /* consume double (8 bytes), no FP */
            ob_str(&o,"<f>",3); continue;
        } else if(c=='%'){ ob_put(&o,'%'); continue; }
        else if(c==0){ break; }
        else { ob_put(&o,'%'); ob_put(&o,c); continue; }
        /* numeric emit with sign/prefix/precision/width */
        int zeros=0; if(prec>=0){ if(nlen<prec) zeros=prec-nlen; zero=0; }
        int bodylen = (sign?1:0)+preflen+zeros+nlen;
        int pad = width-bodylen;
        if(!left && !zero) while(pad-->0) ob_put(&o,' ');
        if(sign) ob_put(&o,sign);
        ob_str(&o,prefix,preflen);
        if(!left && zero) while(pad-->0) ob_put(&o,'0');
        while(zeros-->0) ob_put(&o,'0');
        ob_str(&o,numbuf,nlen);
        if(left) while(pad-->0) ob_put(&o,' ');
    }
    if(cap) o.buf[o.len<o.cap?o.len:o.cap-1]=0;
    if(cap && o.len>=cap) o.buf[cap-1]=0;
    return (int)o.len;
}

int vsnprintf(char *b, unsigned long n, const char *fmt, va_list ap){ return _vformat(b,n,fmt,ap); }
int vsprintf(char *b, const char *fmt, va_list ap){ return _vformat(b, 0x7fffffff, fmt, ap); }
int snprintf(char *b, unsigned long n, const char *fmt, ...){ va_list ap; va_start(ap,fmt); int r=_vformat(b,n,fmt,ap); va_end(ap); return r; }
int sprintf(char *b, const char *fmt, ...){ va_list ap; va_start(ap,fmt); int r=_vformat(b,0x7fffffff,fmt,ap); va_end(ap); return r; }
int vfprintf(FILE *f, const char *fmt, va_list ap){ char t[4096]; int n=_vformat(t,sizeof t,fmt,ap); int w=n<(int)sizeof t?n:(int)sizeof t-1; fwrite(t,1,w,f); return n; }
int fprintf(FILE *f, const char *fmt, ...){ va_list ap; va_start(ap,fmt); int r=vfprintf(f,fmt,ap); va_end(ap); return r; }
int printf(const char *fmt, ...){ va_list ap; va_start(ap,fmt); int r=vfprintf(&_f_stdout,fmt,ap); va_end(ap); return r; }
int vprintf(const char *fmt, va_list ap){ return vfprintf(&_f_stdout,fmt,ap); }

/* ---- minimal sscanf: supports whitespace, literals, %d %i %u %o %x %s %c %n with optional width ---- */
static int hexval(int c){ if(c>='0'&&c<='9') return c-'0'; if(c>='a'&&c<='f') return c-'a'+10; if(c>='A'&&c<='F') return c-'A'+10; return -1; }
int vsscanf(const char *s, const char *fmt, va_list ap){
    int assigned=0;
    while(*fmt){
        if(isspace((unsigned char)*fmt)){ while(isspace((unsigned char)*s)) s++; fmt++; continue; }
        if(*fmt!='%'){ if(*s!=*fmt) break; s++; fmt++; continue; }
        fmt++;
        int suppress=0; if(*fmt=='*'){ suppress=1; fmt++; }
        int width=0; int havew=0; while(isdigit((unsigned char)*fmt)){ width=width*10+(*fmt-'0'); havew=1; fmt++; }
        while(*fmt=='l'||*fmt=='h'||*fmt=='z'||*fmt=='L'||*fmt=='j'||*fmt=='t') fmt++;
        char c=*fmt++;
        if(c=='n'){ if(!suppress){ *va_arg(ap,int*)=0; } continue; }
        if(c!='c') while(isspace((unsigned char)*s)) s++;
        if(c=='d'||c=='i'||c=='u'||c=='x'||c=='X'||c=='o'){
            int base = (c=='x'||c=='X')?16:(c=='o')?8:10;
            int neg=0; const char *start=s;
            if(*s=='+'||*s=='-'){ neg=*s=='-'; s++; }
            if(c=='i'){ if(s[0]=='0'&&(s[1]=='x'||s[1]=='X')){ base=16; s+=2; } else if(s[0]=='0'){ base=8; } }
            else if((c=='x'||c=='X') && s[0]=='0'&&(s[1]=='x'||s[1]=='X')) s+=2;
            unsigned long val=0; int any=0; int cnt=0;
            while(*s && (!havew || cnt<width)){ int d = base==16?hexval((unsigned char)*s):((*s>='0'&&*s<'0'+ (base<10?base:10))?*s-'0':-1); if(base==16 && d<0) break; if(base!=16 && d<0) break; val=val*base+d; s++; any=1; cnt++; }
            if(!any){ s=start; break; }
            if(!suppress){ if(neg) val=(unsigned long)(-(long)val); *va_arg(ap,int*)=(int)val; assigned++; }
        } else if(c=='s'){
            char *out = suppress?0:va_arg(ap,char*); int cnt=0;
            while(*s && !isspace((unsigned char)*s) && (!havew||cnt<width)){ if(out) *out++=*s; s++; cnt++; }
            if(cnt==0) break; if(out) *out=0; if(!suppress) assigned++;
        } else if(c=='c'){
            int cnt = havew?width:1; char *out = suppress?0:va_arg(ap,char*);
            for(int i=0;i<cnt;i++){ if(!*s) break; if(out) *out++=*s; s++; }
            if(!suppress) assigned++;
        } else if(c=='%'){ if(*s!='%') break; s++; }
        else break;
    }
    return assigned;
}
int sscanf(const char *s, const char *fmt, ...){ va_list ap; va_start(ap,fmt); int r=vsscanf(s,fmt,ap); va_end(ap); return r; }

void __assert_fail(const char *e, const char *file, int line, const char *fn){
    fprintf(stderr, "Assertion failed: %s (%s:%d %s)\n", e, file, line, fn);
    for(;;){}
}
